package com.xiahu.reader;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
/** Local quotes and stable locations; independent of account/history/cache. */
final class BookmarkStore {
 private final SharedPreferences prefs;BookmarkStore(Context c){this(c,"reader_bookmarks");}BookmarkStore(Context c,String name){prefs=c.getSharedPreferences(name,0);}
 synchronized JSONArray all()throws Exception{return new JSONArray(prefs.getString("items","[]"));}
 static String text(JSONObject o,String key,int max){String s=o.optString(key);return s.substring(0,Math.min(max,s.length()));}
 static JSONObject anchor(JSONObject a)throws Exception{if(a==null||!a.optString("key").matches("[it]:[a-f0-9]{16}:[0-9]{1,6}"))return null;return new JSONObject().put("key",a.getString("key")).put("index",Math.max(0,Math.min(100000,a.optInt("index")))).put("fragment",Math.max(0,Math.min(100000,a.optInt("fragment")))).put("fraction",Math.max(0,Math.min(1,a.optDouble("fraction",0)))).put("at",Math.max(0,Math.min(1,a.optDouble("at",0)))).put("headroom",Math.max(0,Math.min(1,a.optDouble("headroom",0))));}
 synchronized JSONArray save(JSONObject input)throws Exception{String id=input.optString("id"),bid=input.optString("bookId"),source=input.optString("source"),quote=text(input,"quote",4000);if(!id.matches("bm_[a-z0-9_]{1,80}")||!bid.matches("[A-Za-z0-9_:-]{1,100}")||!Arrays.asList("local","online").contains(source)||quote.trim().isEmpty())throw new IOException("书签内容无效，请重新选择文字");JSONObject clean=new JSONObject().put("id",id).put("bookId",bid).put("source",source).put("quote",quote);for(String key:new String[]{"bookTitle","chapterTitle","chapterKey","author","cover","category"})clean.put(key,text(input,key,key.equals("category")?40:300));clean.put("index",Math.max(0,input.optInt("index"))).put("chapterId",Math.max(0,input.optInt("chapterId"))).put("ratio",Math.max(0,Math.min(1,input.optDouble("ratio",0)))).put("time",input.optLong("time",System.currentTimeMillis()));JSONObject a=anchor(input.optJSONObject("anchor"));if(a!=null)clean.put("anchor",a);JSONArray before=all(),result=new JSONArray();result.put(clean);for(int i=0;i<before.length();i++)if(!id.equals(before.getJSONObject(i).optString("id")))result.put(before.getJSONObject(i));if(result.length()>1000||result.toString().length()>2*1024*1024)throw new IOException("书签空间已满，请整理部分书签");write(result);return result;}
 synchronized JSONArray remove(String id)throws Exception{JSONArray result=new JSONArray(),before=all();for(int i=0;i<before.length();i++)if(!id.equals(before.getJSONObject(i).optString("id")))result.put(before.getJSONObject(i));write(result);return result;}
 private void write(JSONArray v)throws IOException{if(!prefs.edit().putString("items",v.toString()).commit())throw new IOException("书签保存失败，请检查可用空间");}
}
